<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreCart {
 public static function token(PDO $db,array|false|null $actor=null):string {
 $actor=$actor?:Security::user($db);$guest=$_SESSION['store_guest_cart']??null;
 if($actor&&MemberSchema::ready($db)&&MobileAuth::verified($db,$actor)){$token=MemberServices::cart($db,$actor);if(is_string($guest)&&$guest!==$token){Db::transaction($db,function()use($db,$guest,$token,$actor){Db::query($db,'SELECT token FROM carts WHERE token=?'.StoreAccess::lock($db),[$token])->fetch();Db::query($db,'UPDATE store_cart_lines SET cart_token=? WHERE cart_token=?',[$token,$guest]);Db::query($db,'UPDATE store_files SET cart_token=?,owner_id=? WHERE cart_token=? AND item_id IS NULL',[$token,$actor['id'],$guest]);});unset($_SESSION['store_guest_cart']);}}
 else {$token=$guest;if(!is_string($token)||!Db::query($db,'SELECT token FROM carts WHERE token=?',[$token])->fetchColumn()){$token=bin2hex(random_bytes(32));Db::insert($db,'carts',['token'=>$token,'created_at'=>date(DATE_ATOM)]);$_SESSION['store_guest_cart']=$token;}}
 if(!Db::query($db,'SELECT cart_token FROM store_cart_imports WHERE cart_token=?',[$token])->fetchColumn())Db::transaction($db,function()use($db,$token){Db::query($db,'SELECT token FROM carts WHERE token=?'.StoreAccess::lock($db),[$token])->fetch();if(Db::query($db,'SELECT cart_token FROM store_cart_imports WHERE cart_token=?',[$token])->fetchColumn())return;foreach(Db::query($db,'SELECT * FROM cart_items WHERE cart_token=?',[$token])->fetchAll() as $old)Db::insert($db,'store_cart_lines',['cart_token'=>$token,'variant_id'=>$old['variant_id'],'quantity'=>$old['quantity'],'payload'=>'{}','quoted_price'=>0,'created_at'=>date(DATE_ATOM)]);Db::insert($db,'store_cart_imports',['cart_token'=>$token,'created_at'=>date(DATE_ATOM)]);});return $token;
 }
 public static function product(PDO $db,int $variant):array {$v=Db::query($db,'SELECT v.*,COALESCE(d.active,1) AS active,COALESCE(d.unlimited,0) AS unlimited FROM variants v LEFT JOIN store_variant_details d ON d.variant_id=v.id WHERE v.id=?',[$variant])->fetch();if(!$v||!$v['active'])throw new HttpError(422,'گونه فعال پیدا نشد.');$p=(new StoreCatalog($db))->get((int)$v['product_id']);return [$p,$v];}
 public static function add(PDO $db,array|false $actor,int $variant,int $quantity,array $values=[],int $line=0):int {
 $token=self::token($db,$actor);[$p,$v]=self::product($db,$variant);if($p['pricing']==='quote')throw new HttpError(422,'این محصول به استعلام قیمت نیاز دارد.');if($quantity<1||$quantity>99||(!$v['unlimited']&&$quantity>$v['stock']))throw new HttpError(422,'تعداد یا موجودی کافی نیست.');$form=StoreForms::forProduct($db,$p);$payload=StoreForms::validate($db,$form,$values,$token);$price=StoreAccess::money((int)($v['sale_price']??$v['price'])+$payload['surcharge']);
 return Db::transaction($db,function()use($db,$token,$variant,$quantity,$payload,$price,$line){foreach($payload['files'] as &$fid){$original=$fid;$file=Db::query($db,'SELECT * FROM store_files WHERE id=? AND cart_token=? AND item_id IS NULL',[$fid,$token])->fetch();if(!$file)throw new HttpError(422,'پیوست معتبر نیست.');unset($file['id']);$fid=Db::insert($db,'store_files',$file);if(isset($payload['values'][$file['field_key']])&&is_array($payload['values'][$file['field_key']]))foreach($payload['values'][$file['field_key']] as &$value)if((int)$value===$original)$value=$fid;unset($value);}unset($fid);Db::query($db,'SELECT token FROM carts WHERE token=?'.StoreAccess::lock($db),[$token])->fetch();if((int)Db::query($db,'SELECT COUNT(*) FROM store_cart_lines WHERE cart_token=?',[$token])->fetchColumn()>100)throw new HttpError(422,'سبد بیش از حد بزرگ است.');if($line){if(!Db::query($db,'SELECT id FROM store_cart_lines WHERE id=? AND cart_token=?',[$line,$token])->fetchColumn())throw new HttpError(404,'ردیف سبد پیدا نشد.');Db::query($db,'UPDATE store_cart_lines SET variant_id=?,quantity=?,payload=?,quoted_price=? WHERE id=?',[$variant,$quantity,Protocol::encode($payload),$price,$line]);return $line;}return Db::insert($db,'store_cart_lines',['cart_token'=>$token,'variant_id'=>$variant,'quantity'=>$quantity,'payload'=>Protocol::encode($payload),'quoted_price'=>$price,'created_at'=>date(DATE_ATOM)]);});
 }
 public static function quantity(PDO $db,array|false $actor,int $id,int $quantity):void {$token=self::token($db,$actor);$row=Db::query($db,'SELECT * FROM store_cart_lines WHERE id=? AND cart_token=?',[$id,$token])->fetch();if(!$row)throw new HttpError(404,'ردیف سبد پیدا نشد.');if($quantity===0){Db::query($db,'DELETE FROM store_cart_lines WHERE id=?',[$id]);return;}self::add($db,$actor,(int)$row['variant_id'],$quantity,Protocol::decode($row['payload'])['values']??[],$id);}
 public static function items(PDO $db,array|false $actor):array {$token=self::token($db,$actor);$rows=Db::query($db,'SELECT * FROM store_cart_lines WHERE cart_token=? ORDER BY id',[$token])->fetchAll();foreach($rows as &$r){try{[$p,$v]=self::product($db,(int)$r['variant_id']);$old=Protocol::decode($r['payload']);$form=StoreForms::forProduct($db,$p);$payload=StoreForms::validate($db,$form,$old['values']??[],$token);$r+=['product'=>$p,'variant'=>$v,'data'=>$payload,'price'=>StoreAccess::money((int)($v['sale_price']??$v['price'])+$payload['surcharge']),'error'=>''];}catch(HttpError $e){$r+=['error'=>$e->getMessage(),'price'=>0,'data'=>Protocol::decode($r['payload'])];}}unset($r);return $rows;}
}
